func main() {
	n, m := readInt(), readInt()
	parent := make([]int, n+m)
	size := make([]int, n+m)
	for i := range parent {
		parent[i], size[i] = i, 1
	}
	find := func(x int) int {
		for parent[x] != x {
			parent[x] = parent[parent[x]]
			x = parent[x]
		}
		return x
	}
	active := make([]bool, n)
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			if readInt() != 1 {
				continue
			}
			active[i] = true // rook = edge between row i and column j
			a, b := find(i), find(n+j)
			if a != b {
				if size[a] < size[b] {
					a, b = b, a
				}
				parent[b] = a
				size[a] += size[b]
			}
		}
	}
	roots := map[int]bool{}
	for i := 0; i < n; i++ {
		if active[i] {
			roots[find(i)] = true
		}
	}
	fmt.Println(len(roots))
}

